cssCode:
.tracer-wrap { height: 250vh; width: 100%; position: relative; }
.tracer-sticky {
  position: sticky; top: 0; height: 100vh; width: 100%;
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
.tracer-svg { width: 80%; height: 80%; filter: drop-shadow(0 0 15px #00ffcc); }
.tracer-path {
  fill: none; stroke: #00ffcc; stroke-width: 8; stroke-linecap: round;
}
.scroll-hint {
  position: absolute; bottom: 20px; color: #555; font-family: sans-serif; font-weight: bold;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#000;';

const wrap = document.createElement('div');
wrap.className = 'tracer-wrap';

const sticky = document.createElement('div');
sticky.className = 'tracer-sticky';
sticky.innerHTML = '<div class="scroll-hint">SCROLL TO DRAW ↓</div>';

const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
svg.setAttribute("class", "tracer-svg");
svg.setAttribute("viewBox", "0 0 100 100");

// એક સુંદર વળાંક વાળો પાથ
const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
path.setAttribute("class", "tracer-path");
path.setAttribute("d", "M 10 10 C 50 10, 50 90, 90 90");
svg.appendChild(path);
sticky.appendChild(svg);
wrap.appendChild(sticky);
c.appendChild(wrap);

const pathLength = path.getTotalLength();
path.style.strokeDasharray = pathLength;
path.style.strokeDashoffset = pathLength;

c.addEventListener('scroll', () => {
  const maxScroll = c.scrollHeight - c.clientHeight;
  const progress = c.scrollTop / maxScroll;
  // સ્ક્રોલ મુજબ લાઈન દોરાશે
  const drawLength = pathLength * progress;
  path.style.strokeDashoffset = pathLength - drawLength;
});
